"use client";

import { useEffect, useMemo, useRef } from "react";
import { usePlayback, effectiveDuration } from "@/lib/playback-store";
import { durationToSeconds } from "@/lib/walls";
import { getVoice } from "@/lib/voices";
import { cn } from "@/lib/utils";

/**
 * Beveled phone display with REAL audio playback.
 *
 * The phone screen now plays the spoken-lyrics MP3 generated by Z.ai's TTS
 * engine (see /api/audio). A real <audio> element is owned by this component
 * and bound to the store via:
 *  - audioRef.current.src ← track.audioUrl
 *  - ontimeupdate → store.onTimeUpdate
 *  - onloadedmetadata → store.onLoadedMetadata
 *  - onended → store.onEnded
 *  - onerror → store.onError
 *
 * If the audio URL isn't ready yet (TTS still generating in the background),
 * we poll /api/audio?episodeId=...&voice=... every 2s until it returns a
 * URL, then load it into the element and auto-start playback.
 *
 * Lyric captions now sync to the actual audio position via ontimeupdate —
 * no more fake 1s ticker.
 */
export function PhoneDisplay() {
  const track = usePlayback((s) => s.track);
  const isPlaying = usePlayback((s) => s.isPlaying);
  const positionSec = usePlayback((s) => s.positionSec);
  const durationSec = usePlayback((s) => s.durationSec);
  const playEntire = usePlayback((s) => s.playEntireClip);
  const volume = usePlayback((s) => s.volume);
  const audioLoading = usePlayback((s) => s.audioLoading);
  const audioError = usePlayback((s) => s.audioError);
  const activeWallId = usePlayback((s) => s.activeWallId);
  const toggle = usePlayback((s) => s.toggle);
  const restart = usePlayback((s) => s.restart);
  const seek = usePlayback((s) => s.seek);
  const setPlayEntire = usePlayback((s) => s.setPlayEntireClip);
  const setVolume = usePlayback((s) => s.setVolume);
  const onTimeUpdate = usePlayback((s) => s.onTimeUpdate);
  const onLoadedMetadata = usePlayback((s) => s.onLoadedMetadata);
  const onEnded = usePlayback((s) => s.onEnded);
  const onError = usePlayback((s) => s.onError);
  const setAudioLoading = usePlayback((s) => s.setAudioLoading);
  const setAudioUrl = usePlayback((s) => s.setAudioUrl);
  const isPlayingRef = usePlayback((s) => s.isPlaying);
  const playEntireRef = usePlayback((s) => s.playEntireClip);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // === Wire the <audio> element to the store. ===
  // Whenever the track changes, load the new src.
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track) return;
    if (track.audioUrl) {
      // Only set src if it's actually different — setting the same src
      // restarts the audio, which we don't want.
      if (!audio.src.endsWith(track.audioUrl)) {
        audio.src = track.audioUrl;
        audio.load();
      }
    } else {
      // No audio URL yet — start polling.
      audio.src = "";
    }
  }, [track?.audioUrl, track?.episodeId]);

  // === Apply play / pause to the audio element. ===
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track || !track.audioUrl) return;
    if (isPlaying && audio.paused) {
      audio.play().catch((e) => {
        console.error("Audio play() failed:", e);
        onError(e instanceof Error ? e.message : "Playback failed.");
      });
    } else if (!isPlaying && !audio.paused) {
      audio.pause();
    }
  }, [isPlaying, track?.audioUrl, track?.episodeId, onError, track]);

  // === Apply volume. ===
  useEffect(() => {
    const audio = audioRef.current;
    if (audio) audio.volume = Math.max(0, Math.min(1, volume / 100));
  }, [volume]);

  // === Apply seek when positionSec changes externally (e.g. via progress bar). ===
  // We track the last seek we applied to avoid loops with ontimeupdate.
  const lastSeekRef = useRef(-1);
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track || !track.audioUrl) return;
    const diff = Math.abs(audio.currentTime - positionSec);
    if (diff > 1.5) {
      audio.currentTime = positionSec;
    }
    lastSeekRef.current = positionSec;
  }, [positionSec, track?.audioUrl, track]);

  // === Poll for audio URL while we wait for TTS to finish. ===
  useEffect(() => {
    if (!track || track.audioUrl) return;
    if (!audioLoading) setAudioLoading(true);
    let cancelled = false;
    const poll = async () => {
      try {
        const url = `/api/audio?episodeId=${encodeURIComponent(
          track.episodeId
        )}&voice=${encodeURIComponent(track.voice)}`;
        const res = await fetch(url, { cache: "no-store" });
        if (!res.ok) return;
        const j = await res.json();
        if (cancelled) return;
        if (j.hasAudio && j.audioUrl) {
          setAudioUrl(j.audioUrl, j.durationSec || 0);
        }
      } catch (e) {
        console.error("Audio poll failed:", e);
      }
    };
    poll();
    const interval = setInterval(poll, 2500);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [track?.episodeId, track?.audioUrl, track?.voice, audioLoading, setAudioLoading, setAudioUrl, track]);

  // === Parse lyrics into a flat list of lines for caption scrolling. ===
  const lyricsText = track?.lyrics ?? "";
  const lyricLines = useMemo(() => {
    if (!lyricsText) return [];
    const lines: { text: string; tag?: string }[] = [];
    let currentTag: string | undefined;
    for (const raw of lyricsText.split(/\r?\n/)) {
      const trimmed = raw.trim();
      const m = trimmed.match(/^\[([A-Z][A-Z0-9 ]*?)\]$/i);
      if (m) {
        currentTag = m[1].toUpperCase();
        continue;
      }
      if (!trimmed) continue;
      lines.push({ text: trimmed, tag: currentTag });
    }
    return lines;
  }, [lyricsText]);

  // === Pick the "current" lyric line based on actual audio position. ===
  const currentLineIdx = useMemo(() => {
    if (!track || lyricLines.length === 0) return -1;
    const dur = effectiveDuration(track, playEntire);
    if (dur <= 0) return 0;
    const ratio = positionSec / dur;
    const idx = Math.min(
      lyricLines.length - 1,
      Math.floor(ratio * lyricLines.length)
    );
    return idx;
  }, [track, playEntire, positionSec, lyricLines]);

  const brandColor = track?.brandColor || "#722F37";
  const durSec = track ? effectiveDuration(track, playEntire) : 0;
  const progressPct = durSec > 0 ? Math.min(100, (positionSec / durSec) * 100) : 0;
  const fmtTime = (s: number) =>
    `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
  const voiceDef = getVoice(track?.voice);

  // True if we should show the "audio still generating" overlay.
  const showGeneratingOverlay =
    track && audioLoading && !audioError;
  const showErrorOverlay = track && audioError && !audioLoading;

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative mx-auto" style={{ width: 280, height: 580 }}>
        {/* Hidden audio element — driven by the effects above. */}
        <audio
          ref={audioRef}
          preload="auto"
          onTimeUpdate={(e) => {
            const a = e.currentTarget;
            onTimeUpdate(a.currentTime, a.duration || 0);
          }}
          onLoadedMetadata={(e) => onLoadedMetadata(e.currentTarget.duration || 0)}
          onEnded={() => onEnded()}
          onError={(e) => {
            // The DOM error event doesn't expose the message cleanly.
            const code = e.currentTarget.error?.code;
            const msg =
              code === 1
                ? "Loading aborted."
                : code === 2
                ? "Network error while loading audio."
                : code === 3
                ? "Audio decode failed."
                : code === 4
                ? "Audio source not supported."
                : "Unknown audio error.";
            onError(msg);
          }}
        />

        {/* === BEVELED PHONE FRAME === */}
        <div
          className="absolute inset-0 rounded-[3rem]"
          style={{
            background:
              "linear-gradient(145deg, oklch(0.78 0.02 60) 0%, oklch(0.32 0.02 50) 35%, oklch(0.22 0.02 50) 50%, oklch(0.42 0.02 60) 65%, oklch(0.78 0.02 60) 100%)",
            boxShadow:
              "0 24px 48px -12px oklch(0.2 0.04 30 / 0.45), 0 0 0 1.5px oklch(0.18 0.02 40), inset 0 2px 4px oklch(0.95 0.01 80 / 0.6), inset 0 -2px 4px oklch(0.12 0.02 40)",
          }}
        />
        <div
          className="absolute inset-[3px] rounded-[2.85rem]"
          style={{
            background:
              "linear-gradient(145deg, oklch(0.16 0.01 40) 0%, oklch(0.08 0.01 40) 50%, oklch(0.16 0.01 40) 100%)",
            boxShadow: "inset 0 0 8px oklch(0 0 0 / 0.6)",
          }}
        />
        <div
          className="absolute inset-[10px] rounded-[2.4rem] overflow-hidden flex flex-col"
          style={{
            background: oklchBgFromBrand(brandColor),
          }}
        >
          {/* === STATUS BAR === */}
          <div className="relative z-10 flex items-center justify-between px-5 pt-3 pb-1 text-[0.65rem] font-medium text-white/90">
            <span className="font-mono">
              {fmtTime(positionSec)} / {fmtTime(durSec || durSec || (track ? durationToSeconds(track.episodeDuration) : 0))}
            </span>
            <div className="absolute left-1/2 -translate-x-1/2 top-2 h-5 w-20 rounded-full bg-black/85" />
            <div className="flex items-center gap-1">
              <SignalDots />
              <BatteryIcon />
            </div>
          </div>

          {/* === MUSIC VIDEO STAGE === */}
          <div className="relative flex-1 mx-2 mt-1 mb-2 rounded-2xl overflow-hidden">
            <Visualizer isPlaying={isPlaying} brandColor={brandColor} />

            {/* Episode title overlay */}
            <div className="absolute inset-x-0 top-0 p-3 bg-gradient-to-b from-black/55 to-transparent">
              <p className="text-[0.55rem] uppercase tracking-wider text-white/70 font-semibold">
                {track?.emoji || "🎙️"} · {track?.wallName || "Now Playing"}
              </p>
              <p className="text-white font-serif text-sm leading-tight font-semibold mt-0.5 line-clamp-2 drop-shadow">
                {track?.episodeTitle || "Load a track from the wall"}
              </p>
              {track && (
                <p className="text-[0.55rem] text-white/60 mt-0.5">
                  Voice: {voiceDef.label}
                </p>
              )}
            </div>

            {/* Generating overlay */}
            {showGeneratingOverlay && (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/40 backdrop-blur-sm">
                <div className="h-9 w-9 rounded-full border-2 border-white/40 border-t-white animate-spin" />
                <p className="text-white text-[0.7rem] font-semibold uppercase tracking-wider">
                  Joe is warming up…
                </p>
                <p className="text-white/60 text-[0.6rem]">
                  TTS generating · voice: {voiceDef.label}
                </p>
              </div>
            )}

            {/* Error overlay */}
            {showErrorOverlay && (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-1 bg-black/60 backdrop-blur-sm p-4 text-center">
                <p className="text-red-300 text-[0.7rem] font-semibold">
                  Audio failed
                </p>
                <p className="text-white/70 text-[0.6rem] leading-snug">
                  {audioError}
                </p>
                <button
                  onClick={() => {
                    // Force a re-poll.
                    const t = track;
                    if (!t) return;
                    setAudioLoading(true);
                    usePlayback.setState({ audioError: null });
                  }}
                  className="mt-2 text-[0.65rem] font-semibold text-white/90 underline"
                >
                  Retry
                </button>
              </div>
            )}

            {/* Center play overlay (only when paused, audio ready, not at end) */}
            {!isPlaying && track && track.audioUrl && !showGeneratingOverlay && !showErrorOverlay && (
              <button
                onClick={toggle}
                className="absolute inset-0 flex items-center justify-center group"
                aria-label="Play"
              >
                <span
                  className="flex items-center justify-center h-14 w-14 rounded-full backdrop-blur-md border-2 border-white/50 transition-transform group-hover:scale-105"
                  style={{ background: "oklch(0 0 0 / 0.35)" }}
                >
                  <PlayIcon className="h-6 w-6 text-white ml-0.5" />
                </span>
              </button>
            )}

            {/* Replay overlay (when at end) */}
            {track && track.audioUrl && positionSec >= durSec && durSec > 0 && !showGeneratingOverlay && !showErrorOverlay && (
              <button
                onClick={restart}
                className="absolute inset-0 flex flex-col items-center justify-center gap-1.5 group"
                aria-label="Replay"
              >
                <span
                  className="flex items-center justify-center h-14 w-14 rounded-full backdrop-blur-md border-2 border-white/50 transition-transform group-hover:scale-105"
                  style={{ background: "oklch(0 0 0 / 0.35)" }}
                >
                  <ReplayIcon className="h-6 w-6 text-white" />
                </span>
                <span className="text-[0.6rem] font-semibold text-white/90 uppercase tracking-wider drop-shadow">
                  Tap to Replay
                </span>
              </button>
            )}

            {/* === LYRIC CAPTIONS === */}
            <div className="absolute inset-x-0 bottom-0 p-3 bg-gradient-to-t from-black/85 via-black/40 to-transparent">
              {track ? (
                <>
                  {lyricLines[currentLineIdx]?.tag && (
                    <p className="text-[0.55rem] uppercase tracking-wider text-white/60 font-semibold mb-1">
                      {lyricLines[currentLineIdx].tag}
                    </p>
                  )}
                  <p
                    key={currentLineIdx}
                    className="text-white text-[0.78rem] leading-snug font-medium drop-shadow text-center line-clamp-2 animate-[fadein_0.4s_ease-out]"
                  >
                    {lyricLines[currentLineIdx]?.text || "♪"}
                  </p>
                  {lyricLines[currentLineIdx + 1] && (
                    <p className="text-white/45 text-[0.7rem] leading-snug mt-1 text-center line-clamp-1">
                      {lyricLines[currentLineIdx + 1].text}
                    </p>
                  )}
                </>
              ) : (
                <div className="text-center py-2">
                  <p className="text-white/70 text-[0.7rem] font-medium">
                    Pick a track from the wall →
                  </p>
                  <p className="text-white/40 text-[0.6rem] mt-0.5">
                    Generate a song, then send it to a wall.
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* === PROGRESS BAR === */}
          <div className="px-3 pb-1">
            <div
              className="relative h-1 rounded-full bg-white/15 cursor-pointer"
              onClick={(e) => {
                if (!track || !track.audioUrl) return;
                const rect = e.currentTarget.getBoundingClientRect();
                const ratio = (e.clientX - rect.left) / rect.width;
                seek(ratio * durSec);
              }}
            >
              <div
                className="absolute inset-y-0 left-0 rounded-full"
                style={{
                  width: `${progressPct}%`,
                  background: "linear-gradient(90deg, oklch(0.98 0.02 80), oklch(0.95 0.05 70))",
                }}
              />
              <div
                className="absolute top-1/2 -translate-y-1/2 h-2.5 w-2.5 rounded-full bg-white shadow-md transition-[left]"
                style={{ left: `calc(${progressPct}% - 5px)` }}
              />
            </div>
          </div>

          {/* === TRANSPORT CONTROLS === */}
          <div className="flex items-center justify-center gap-4 py-2 px-3">
            <button
              onClick={restart}
              disabled={!track}
              className="text-white/80 hover:text-white disabled:opacity-30 transition-colors"
              aria-label="Restart"
            >
              <PrevIcon className="h-4 w-4" />
            </button>
            <button
              onClick={toggle}
              disabled={!track}
              className="flex items-center justify-center h-11 w-11 rounded-full bg-white text-black shadow-lg disabled:opacity-30 hover:scale-105 transition-transform"
              aria-label={isPlaying ? "Pause" : "Play"}
            >
              {audioLoading ? (
                <div className="h-5 w-5 rounded-full border-2 border-black/40 border-t-black animate-spin" />
              ) : isPlaying ? (
                <PauseIcon className="h-5 w-5" />
              ) : (
                <PlayIcon className="h-5 w-5 ml-0.5" />
              )}
            </button>
            <button
              onClick={() => seek(positionSec + 5)}
              disabled={!track || !track.audioUrl}
              className="text-white/80 hover:text-white disabled:opacity-30 transition-colors"
              aria-label="Skip 5 seconds"
            >
              <NextIcon className="h-4 w-4" />
            </button>
          </div>

          {/* === HOME INDICATOR === */}
          <div className="flex justify-center pb-2">
            <div className="h-1 w-24 rounded-full bg-white/40" />
          </div>
        </div>

        {/* Side buttons */}
        <div
          className="absolute -left-[3px] top-32 h-12 w-[3px] rounded-l-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
        <div
          className="absolute -left-[3px] top-48 h-16 w-[3px] rounded-l-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
        <div
          className="absolute -right-[3px] top-40 h-20 w-[3px] rounded-r-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
      </div>

      {/* === PLAY ENTIRE CLIP TOGGLE === */}
      <div
        className="w-full max-w-[280px] rounded-lg border border-border/60 bg-card p-3"
        data-active-wall={activeWallId}
      >
        <div className="flex items-center justify-between gap-2">
          <div className="flex-1 min-w-0">
            <p className="text-xs font-semibold text-foreground">
              Play Entire Clip
            </p>
            <p className="text-[0.7rem] text-muted-foreground leading-tight">
              {playEntire
                ? `Full TTS audio (~${track ? durationToSeconds(track.episodeDuration) : 60}s) — Joe's spoken lyrics`
                : `Preview mode — first 12 seconds only`}
            </p>
          </div>
          <button
            role="switch"
            aria-checked={playEntire}
            onClick={() => setPlayEntire(!playEntire)}
            className={cn(
              "relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors",
              playEntire ? "bg-primary" : "bg-muted"
            )}
          >
            <span
              className={cn(
                "inline-block h-5 w-5 transform rounded-full bg-white shadow-lg transition-transform",
                playEntire ? "translate-x-5" : "translate-x-0"
              )}
            />
          </button>
        </div>
        {/* Volume slider */}
        {track && (
          <div className="mt-3 flex items-center gap-2">
            <span className="text-[0.7rem] text-muted-foreground uppercase tracking-wider">
              Vol
            </span>
            <input
              type="range"
              min={0}
              max={100}
              value={volume}
              onChange={(e) => setVolume(parseInt(e.target.value, 10))}
              className="flex-1 h-1 rounded-full accent-primary"
            />
            <span className="text-[0.65rem] font-mono text-muted-foreground w-7 text-right">
              {volume}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Visualizer (animated bars over brand gradient)
// ----------------------------------------------------------------------------

function Visualizer({
  isPlaying,
  brandColor,
}: {
  isPlaying: boolean;
  brandColor: string;
}) {
  const bars = useMemo(
    () =>
      Array.from({ length: 24 }, (_, i) => ({
        base: 0.2 + ((i * 13) % 7) / 10,
        delay: (i % 6) * 0.12,
        duration: 0.7 + ((i * 7) % 5) * 0.08,
      })),
    []
  );

  return (
    <div className="absolute inset-0 overflow-hidden">
      <div
        className="absolute inset-0"
        style={{
          background: `linear-gradient(160deg, ${brandColor} 0%, ${shade(brandColor, -25)} 60%, ${shade(brandColor, -45)} 100%)`,
        }}
      />
      <div
        className="absolute inset-0 opacity-40 mix-blend-overlay"
        style={{
          background:
            "radial-gradient(circle at 30% 30%, oklch(0.99 0.02 80 / 0.7) 0%, transparent 35%), radial-gradient(circle at 70% 70%, oklch(0.98 0.04 70 / 0.5) 0%, transparent 40%)",
          animation: isPlaying ? "drift 8s ease-in-out infinite alternate" : "none",
        }}
      />
      <div className="absolute inset-x-0 bottom-0 h-1/3 flex items-end justify-center gap-[3px] px-4 pb-2 opacity-50">
        {bars.map((b, i) => (
          <div
            key={i}
            className="flex-1 max-w-[6px] rounded-t-sm bg-white/70"
            style={{
              height: isPlaying ? `${b.base * 100}%` : "10%",
              animation: isPlaying
                ? `eq ${b.duration}s ease-in-out ${b.delay}s infinite alternate`
                : "none",
            }}
          />
        ))}
      </div>
      <style jsx global>{`
        @keyframes eq {
          0% { transform: scaleY(0.4); }
          100% { transform: scaleY(1.2); }
        }
        @keyframes drift {
          0% { transform: translate(-4%, -2%) scale(1); }
          100% { transform: translate(4%, 2%) scale(1.05); }
        }
        @keyframes fadein {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Tiny icon components (inline SVG, no extra deps)
// ----------------------------------------------------------------------------

function PlayIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path d="M8 5v14l11-7z" />
    </svg>
  );
}
function PauseIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className}>
      <rect x="6" y="5" width="4" height="14" rx="1" />
      <rect x="14" y="5" width="4" height="14" rx="1" />
    </svg>
  );
}
function ReplayIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className={className}>
      <path d="M3 12a9 9 0 1 0 3-6.7L3 8" />
      <path d="M3 4v4h4" />
    </svg>
  );
}
function PrevIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path d="M6 5h2v14H6zM20 5L9 12l11 7z" />
    </svg>
  );
}
function NextIcon({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" className={className}>
      <path d="M16 5h2v14h-2zM4 5l11 7L4 19z" />
    </svg>
  );
}
function SignalDots() {
  return (
    <div className="flex items-end gap-[1.5px] h-2.5">
      <span className="block w-[2px] h-1 bg-white/80 rounded-sm" />
      <span className="block w-[2px] h-1.5 bg-white/80 rounded-sm" />
      <span className="block w-[2px] h-2 bg-white/80 rounded-sm" />
      <span className="block w-[2px] h-2.5 bg-white/80 rounded-sm" />
    </div>
  );
}
function BatteryIcon() {
  return (
    <div className="flex items-center gap-0.5">
      <span className="block w-5 h-2.5 border border-white/60 rounded-[2px] relative">
        <span className="absolute inset-0.5 bg-white/80 rounded-[1px]" style={{ width: "70%" }} />
      </span>
      <span className="block w-0.5 h-1 bg-white/60 rounded-sm" />
    </div>
  );
}

// ----------------------------------------------------------------------------
// Color helpers
// ----------------------------------------------------------------------------

function oklchBgFromBrand(brand: string): string {
  return `linear-gradient(180deg, ${shade(brand, -55)} 0%, ${shade(brand, -70)} 100%)`;
}

function shade(hex: string, percent: number): string {
  const h = hex.replace("#", "");
  if (h.length !== 6) return hex;
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const f = (c: number) => {
    const v = Math.round(c + (percent / 100) * 255);
    return Math.max(0, Math.min(255, v));
  };
  const toHex = (n: number) => n.toString(16).padStart(2, "0");
  return `#${toHex(f(r))}${toHex(f(g))}${toHex(f(b))}`;
}
